"use strict";(self.webpackChunktest_website=self.webpackChunktest_website||[]).push([[781141],{459171:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>s,contentTitle:()=>h,default:()=>u,frontMatter:()=>i,metadata:()=>o,toc:()=>l});var o=n(901158),r=n(474848),a=n(28453);const i={tags:["occult","2024-12"]},h="\u52d5\u753b\uff1aSkinwalker ranch \u306b\u96a3\u63a5\u3057\u305f\u6240\u6709\u5730\u3067\u8d77\u304d\u308b\u602a\u73fe\u8c61\uff1a\u6587\u5b57\u8d77\u3053\u3057",s={authorsImageUrls:[]},l=[{value:"\u524d\u7f6e\u304d",id:"\u524d\u7f6e\u304d",level:2},{value:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)",id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",level:2},{value:"\u52d5\u753b(1:08:29)",id:"\u52d5\u753b10829",level:2},{value:"\u52d5\u753b\u6982\u8981\u6b04",id:"\u52d5\u753b\u6982\u8981\u6b04",level:3},{value:"FasterWhisper AI(large-v2 model)",id:"fasterwhisper-ailarge-v2-model",level:2}];function d(e){const t={h2:"h2",h3:"h3",hr:"hr",p:"p",...(0,a.R)(),...e.components},{Details:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.h2,{id:"\u524d\u7f6e\u304d",children:"\u524d\u7f6e\u304d"}),"\n",(0,r.jsx)(t.p,{children:'Ryan Burns \u306f Skinwalker ranch \u306e\u5357\u5074\u306b\u96a3\u63a5\u3057\u305f\u571f\u5730\u3092\u8cfc\u5165\u3057\u3066\u6240\u6709\u3057\u3066\u304a\u308a\u3001"Space Wolf Reserch" \u3068\u540d\u4ed8\u3051\u3066\u3044\u308b\u3002'}),"\n",(0,r.jsx)(t.p,{children:"\u305d\u306e\u6240\u6709\u5730\u3067\u8d77\u304d\u305f\u30bf\u30a4\u30c8\u30eb\u306e\u4e8b\u4ef6\u3092\u53d6\u6750\u3057\u305f\u52d5\u753b\u306e \u6587\u5b57\u8d77\u3053\u3057 \u3092\u8a18\u9332\u3057\u3066\u304a\u304f\u3002AI \u51e6\u7406\u7528\u3002"}),"\n",(0,r.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model--deepl2024-07-model",children:"FasterWhisper AI(large-v2 model) + DeepL(2024-07 model)"}),"\n",(0,r.jsx)(t.h2,{id:"\u52d5\u753b10829",children:"\u52d5\u753b(1:08:29)"}),"\n",(0,r.jsx)(t.p,{children:"The Shape of Shadows | Documentary | Full Movie | Supernatural Mysteries"}),"\n",(0,r.jsx)("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/psGlKFXuSZ8?si=2Dizx0IfxZYr5897",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:!0}),"\n",(0,r.jsx)(t.h3,{id:"\u52d5\u753b\u6982\u8981\u6b04",children:"\u52d5\u753b\u6982\u8981\u6b04"}),"\n",(0,r.jsx)(t.p,{children:"111,200 views  2024/03/14"}),"\n",(0,r.jsx)(t.p,{children:"Explore Utah\u2019s Space Wolf Research near Skinwalker Ranch in \u2018The Shape of Shadows,\u2019 featuring U.F.O. sightings, mysterious trackways, a haunting ritual circle, and a high-speed car chase. This is a thrilling journey into Utah\u2019s supernatural mysteries."}),"\n",(0,r.jsx)(t.p,{children:"Stars: Tony Merkel, Joel Thomas, Ward Hiney, Jack Merkel, Christian B. Roper\r\nProduced, Directed by Tony Merkel"}),"\n",(0,r.jsx)(t.h2,{id:"fasterwhisper-ailarge-v2-model",children:"FasterWhisper AI(large-v2 model)"}),"\n",(0,r.jsxs)(n,{children:[(0,r.jsx)("summary",{children:"\u25bc\u6587\u5b57\u8d77\u3053\u3057 \u5c55\u958b"}),(0,r.jsx)(t.p,{children:"Attention!\r\nAlright, you'll be alright.\r\nMy grandfather, too, he would tell the same story.\r\nIn that same area, there was a horse, like a horseman.\r\nSo, there definitely is that creature out there.\r\nSo, they say these things can turn into wolves.\r\nThey turn into, you know, different creatures, cougars, whatever is available.\r\nMy name is Tony Merkel, host of the Confessionals Podcast. I've interviewed over 500 witnesses to the strange and unexplained.\r\n(0:01:23)"}),(0,r.jsx)(t.p,{children:"Last year, I assembled a team of like-minded guys to come with me on a quest to document and even possibly experience some of these mysterious phenomena for ourselves.\r\nWe started getting lights out here over the ridge.\r\nHere they come again.\r\nHere they come again.\r\nThat grey container was right here.\r\nCorrect. Look left, look left.\r\nUp there?\r\nThey'll come from the west, in the sky.\r\n(0:01:47)"}),(0,r.jsx)(t.p,{children:"So, it's old news.\r\nIt's old news, yeah.\r\nThis kind of stuff is connected in some way.\r\nWhat if those guys, whoever was that, was a decoy?\r\nGod created everything, including these UFOs, including all those phenomena.\r\nGod created it all.\r\nIn the summer of 2022, the team got a chance at a trip of a lifetime when a show guest named Ryan invited us to his property called Space Wolf Research. Located in Utah's Uintah Basin, at the very doorstep of the infamous Sherman Ranch, Space Wolf had already produced multiple reports and evidence of strange happenings from skinwalkers to UFOs. It's very interesting how I got into an area that ended up being so restricted and locked down later on because it was so open back then.\r\n(0:02:44)"}),(0,r.jsx)(t.p,{children:"But I had succumbed to an injury.\r\nI was a fishing guide.\r\nI was driving around.\r\nI couldn't work or get my foot wet, so I was driving around doing stuff.\r\nI was coming down that road.\r\nSomething was coming down through there.\r\nAnd I was like, ah, it looks like an elderly Native American. I couldn't tell if it was a he or a she.\r\n(0:03:06)"}),(0,r.jsx)(t.p,{children:"Really?\r\nHad a blanket over their head and came towards the truck.\r\nAnd I rolled down the window and said, hey, you want to get in?\r\nWe arrived somewhere.\r\nThey kind of mumbled something and just kind of grumbled in.\r\nJumped up into the truck.\r\nAnd within seconds, I was just in tears.\r\nI didn't know what was going on.\r\nMy reality just totally changed.\r\nThe Bureau of Indian Affairs found me near Bottle Hollow Reservoir. And I was just kind of hanging out of my truck catatonic.\r\n(0:03:41)"}),(0,r.jsx)(t.p,{children:"They thought I was drunk.\r\nDid all the tests.\r\nThey realized I wasn't. And asked me what happened.\r\nAnd when I told them, they explained to me that I had been nabbed by the skinwalker.\r\nAnd that's the first time I'd ever heard that.\r\nSeeking answers after his own encounter, Ryan would purchase property bordering the Sherman Ranch and attempt to create what he would refer to as a safe haven of sorts for the phenomena.\r\n(0:04:05)"}),(0,r.jsx)(t.p,{children:"No guns, no threats.\r\n(0:04:07)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"So Ryan wants to create a safe haven for all the activity in the area.\r\nSo, you know, if this stuff is conscious and it's bobbing and weaving and ducking behind bushes or whatever trying to avoid human contact, well, he wants to create an environment on his properties where it's just like a place where consciously it's known to be a safe place where nothing's going to happen, you're not going to get shot at kind of thing.\r\n(0:04:32)"}),(0,r.jsx)(t.p,{children:"So whether it's Bigfoot, shadow entities, aliens, UFOs, portals, they're welcome on his property.\r\nSo he has a no-gun policy.\r\nHe doesn't want anybody having guns on the property.\r\nSince episode 202, I've become pretty friendly with Ryan and I respect him.\r\nSo we're going to follow his orders and his wishes and we're going to do this gun-free. So it's going to be interesting.\r\nHopefully nothing too crazy happens that we can't handle with a hatchet, but we'll see.\r\n(0:05:01)"}),(0,r.jsx)(t.p,{children:"So show us the picture that we got.\r\nOh, yeah.\r\nSo apparently Christian's already there.\r\nAnd when they got to the ranch, one of the shipping containers that's on the property was picked up and moved.\r\nBut there was no drag marks when it was moved and there was no tire tracks, nothing around.\r\nIt was just mysteriously moved.\r\nSo this is the picture that was sent right here.\r\n(0:05:35)"}),(0,r.jsx)(t.p,{children:"Oh, I got it, I got it.\r\nThat's the picture right there, which is nuts.\r\nAnd you can tell there's no drag marks, like it was slid.\r\nIt was just picked up in the middle of the night and moved.\r\nThere was nothing on the property.\r\nSo, yeah, this is what we're walking into.\r\nTeleporting shipping containers and we haven't even got there yet.\r\nSo I feel like we're on track to see some wild stuff, I can tell you that.\r\n(0:06:05)"}),(0,r.jsx)(t.p,{children:"I appreciate your time.\r\nOh, thank you. No problem.\r\nAs part of my duty here, you know, I'm security.\r\nRight. So anything that happens out here, I'm supposed to be on top of it.\r\nI am absolutely baffled with how a 9,000 pound container is moved.\r\nNot so much as a blade of grass disturbed.\r\nBecause there's no... it looks like it was picked up and moved.\r\n(0:06:40)"}),(0,r.jsx)(t.p,{children:"There's no scraping.\r\nWasn't it by the building? Right by the building?\r\nYeah, it was next to the building and now it's the other way.\r\nIt's turned, isn't it turned?\r\nIt's completely turned as if it was lifted.\r\nI didn't notice that.\r\nBut I came out here and I go... Oh. That gray container was right here.\r\nCorrect. And no skid marks, it's been skid by, right?\r\n(0:07:03)"}),(0,r.jsx)(t.p,{children:"That end right there was right there.\r\nI mean, a couple of years before, there was a 40 foot RV almost exactly where the container was that was vaporized by what was apparently a daytime lightning bolt.\r\nWell, we have pictures of the lightning strike.\r\nRyan has them and I got them too.\r\nAnd they estimated that a 12 foot bolt hit the trailer and melted it.\r\n(0:07:29)"}),(0,r.jsx)(t.p,{children:"The lightning was getting kind of close and I told my husband, we better go in the house.\r\n(0:07:33)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"I was getting pretty close and then boom, it hit right across the street.\r\nAnd we called the fire department and it was melted down, that whole trailer, within seconds.\r\nIt went like this.\r\nSo it had to be lifted up.\r\nYeah. Here's a little bit of evidence.\r\nIt wasn't lifted that high because it caught this rock.\r\nLook it.\r\nIt caught that rock and it caught this one.\r\n(0:08:01)"}),(0,r.jsx)(t.p,{children:"It caught those three.\r\nIt caught those rocks and moved them.\r\nBut it had to be up high.\r\nWhat would it take to melt metal into rock?\r\nI mean, would a lightning bolt do that?\r\nAlright, so we've been here at this location for, I don't know, like six hours.\r\nYou're going to freak out when you get here.\r\nThere's some stuff that's totally unexplainable already.\r\n(0:08:32)"}),(0,r.jsx)(t.p,{children:"Really?\r\nYeah, we've met some of the neighbors. They told us stuff that's going to blow your mind.\r\nLet me tell you this.\r\nSome of the words that we were told.\r\nGiant red-headed cannibals.\r\nGiant red-headed what?\r\nWhat?\r\nWoo!\r\nHold on a sec.\r\nGiant red-headed what?\r\nLet's go, baby!\r\nBut one of the Native American Indians that we've been hanging out with here told us about giant red-headed cannibals.\r\n(0:09:03)"}),(0,r.jsx)(t.p,{children:"You'll learn more about that.\r\nWater babies that are evil.\r\nWhat?\r\nYeah. And what do you call star people?\r\nStar people.\r\nThe star people that fly.\r\nLet's go!\r\nOh, let's go.\r\nWell, just trying to find some gas before we run out of gas.\r\nNothing major to see here.\r\nWhere are we, Tony?\r\nI honestly don't know. Kansas, I believe?\r\nThis is Wakini. Wakini?\r\nThis is downtown Wakini. Downtown Wakini is closed.\r\n(0:09:39)"}),(0,r.jsx)(t.p,{children:"How we doing?\r\nOh, fantastic.\r\nYeah. Fantastic. You get killed by a serial killer before we even get there.\r\nYeah. Geez, we're not worried about the skinwalkers.\r\nWe're worried about getting picked up in Wakini by the guy from So I Know What You Did Last Summer, you know?\r\nWakini looks like a waste.\r\nThere's nothing going on here.\r\nI've never seen this empty of a town.\r\n(0:10:17)"}),(0,r.jsx)(t.p,{children:"That's what the Wakini Whacker wants you to think.\r\nWith Christian and Joseph already reporting sightings, we raced through the night to get there.\r\nAs the rest of the crew continued our 30-hour drive, they settled in for their first night at Space Wolf Research. But as we've always heard, when the sun goes down, the land comes alive.\r\nI came out here to produce a movie.\r\n(0:10:52)"}),(0,r.jsx)(t.p,{children:"I didn't plan on being in a movie.\r\nI've seen these shows. I'm a filmmaker.\r\nBut when you have a real experience, like when we were looking through the binoculars and you shot that film through your iPhone and then you blew it up.\r\nI don't know what that was flying through.\r\nBut then last night, that was it, man.\r\nI don't... I just... I don't... Listen, if he doesn't want to pay... I don't know.\r\n(0:11:26)"}),(0,r.jsx)(t.p,{children:"I need some coffee, though. Maybe I'll feel different.\r\nBut last night, that was... there was a constant... it wasn't a hum.\r\n(0:11:34)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"It was more like a rolling growl.\r\nLike... like a... It was like if the valley was snoring.\r\nIt just... it just kept going and going.\r\nSo much so that I got out of my tent and I went and slept in my truck.\r\nArriving in Utah, we knew we would be walking into a very active situation.\r\nNot only had Christian and Joseph had a rough first night, but according to locals, the last few days had seen a spike in activity on the property.\r\n(0:12:06)"}),(0,r.jsx)(t.p,{children:"Finally pulling into our campsite at Space Wolf, we all felt heaviness and the surreal realization that we stood on the doorstep of one of the most infamous hubs of high strangeness in the world.\r\nWell, the first thing we did when we got here is we set up, looking out at the mesa there, the binoculars on a tripod.\r\nAnd we were just hanging out looking and I saw, and you'll see right across here, is some big solar panels.\r\n(0:12:40)"}),(0,r.jsx)(t.p,{children:"But from here at first it looked like a truck.\r\nAnd then there's a big tower... and what we figured out is at night it's solar panels that charge the light.\r\nAnd so as at night there's a red light and a white light and the white light turns... it blinks.\r\nI think it's so maybe some flames don't hit the mesa or I don't know.\r\n(0:12:58)"}),(0,r.jsx)(t.p,{children:"But then Christine and I were like, let's see if we can hold our camera up to the lens of the binoculars.\r\nAnd he started shooting and then I said, did you get that?\r\nAnd an object went down, over, and straight up.\r\nWe only got the part of it crossing the frame.\r\nHere, I'll show you.\r\nWhat you're seeing right now is... this is the binocular circle and then the camera pushed up against it, alright?\r\n(0:13:37)"}),(0,r.jsx)(t.p,{children:"Okay. Now, that's what I'm focusing on. That's the solar panels with the lights.\r\nOkay. Right? And again, we were just like, well, let's see what this place is like. I have no idea.\r\nAnd now watch this area right around here.\r\nOh, shoot, sorry.\r\nI saw it.\r\nOh, wow.\r\nNow we slow it down.\r\nHuh. Wow. Now we slow it down again and he pulls in on it.\r\n(0:14:13)"}),(0,r.jsx)(t.p,{children:"Wow, what is that?\r\nIt's crazy when you slow it up.\r\nYeah, watch compared to that tree, that whole tree right there.\r\nYeah. It's pretty big.\r\nYeah. Wow. Wow. It looks almost like it's cloaking, too.\r\nBut then, once it left frame, it went... and then I couldn't see it anymore.\r\nAnd you saw it with your naked eye.\r\nI saw it with my naked eye. He was holding his camera. That's your camera.\r\n(0:15:02)"}),(0,r.jsx)(t.p,{children:"He was holding it there and, you know, you see how he's trying to get it to like... and we were just trying to get to see what this was, to get video of this.\r\nAnd I went, whoa, did you see that? And he goes, what? And he looked back because he knew something was there.\r\n(0:15:16)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"But I'm like, it just went through and then up.\r\nWow. You know, and just a slightly different angle down lower, we would have not been able to catch that on camera.\r\nRight. Primed to expect the UFO activity after seeing what Christian and Joseph had captured, we decided to take a quick hike of the property before it got dark.\r\nAs it would turn out, Space Wolf had something altogether different waiting for us.\r\n(0:15:38)"}),(0,r.jsx)(t.p,{children:"We've been looking at this trackway and these are what we're seeing here.\r\nThis is obviously footprints going down this way.\r\nThis is one that we have, we feel like has toes involved in it.\r\nAnd as it goes down here, my personal thought is it's almost as if somebody was standing here in the side waiting to make sure it's all good.\r\n(0:16:01)"}),(0,r.jsx)(t.p,{children:"Like they're standing this way, looking, and then they turned and started going down this way.\r\nAnd as they went down, so like this foot here, and then you come out here and it's like one, two.\r\nAnd then as we go here, now the footprints, these longer footprints are over, they're done.\r\nAnd now we have these hooves that develop into the ground here.\r\nAnd as it goes all the way down here, we've been able to track it all the way to the fence.\r\n(0:16:30)"}),(0,r.jsx)(t.p,{children:"And almost like it jumped the fence then and went through the mound on the other side of the fence.\r\nBefore any of the other stuff popped off, that was the first interaction that we had that we knew that we were on some weird, weird stuff.\r\nWhat do you guys make of the burns?\r\nWell, see, that's the weird thing, right?\r\nYou're thinking maybe lightning, but it's just burned all the way down.\r\n(0:16:55)"}),(0,r.jsx)(t.p,{children:"And it's burnt as well? Aw, man.\r\nThe lightning along the path is weird.\r\nAll over it, the whole path.\r\nThe one thing I will say is there's no like, when lightning hits, it explodes the trees, and there's no like exploded burned pieces.\r\nRight, it's just like touched and burned.\r\nDo you think there could be that many lightning strikes, like, this close together?\r\nYeah, but it's like it's cut with a burn.\r\n(0:17:23)"}),(0,r.jsx)(t.p,{children:"Oh, my God. Like this is burnt through and through.\r\nThat is. Wow. Oh, my God. Blown into a chauffeur?\r\nThat's the poster.\r\nOut here, there's all these prints that went over the mound here.\r\nAnd it's just a theory, but that we followed the tracks coming over to this way, and it was like something jumped over the fence and then went over that.\r\nWhat doesn't make sense is if it's an animal.\r\n(0:17:54)"}),(0,r.jsx)(t.p,{children:"To me, I would think an animal would go around it.\r\nI don't know why an animal would go over it, but... So when we came out here, the whole crew agreed we wanted to really take the experiential narrative of the Native American people that had lived in this area for generations and put it front and center, rather than doing the typical paranormal show thing with EMF meters and trying to prove something scientifically.\r\n(0:18:16)"}),(0,r.jsx)(t.p,{children:"We thought the continued experience of these people was at least as much proof as any amount of scientific data we could have gathered.\r\n(0:18:23)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"Both Standing Rock and Johnny Gamachippee were the two tribal members that spent the most time with us.\r\nAnd when we found this set of tracks, we were careful to ask each of them to look at it independently so that one couldn't unintentionally sway the other.\r\nSo before we get down in here and show you what we found, can you just tell me a little bit how you feel about this area?\r\n(0:18:46)"}),(0,r.jsx)(t.p,{children:"Because I know up there you said it kind of felt heavy.\r\nYeah, just more heavier.\r\nI think the more closer we get to around this area, I think I just get more nervous.\r\nBecause of the drill?\r\nSomething, yeah.\r\nSo right down this trail is where the series of prints start that Joel and Ward found.\r\nAnd so we're going to show you this and then we're going to come down here and I'm going to show you what we found with these tree branches that seems pretty bizarre.\r\n(0:19:16)"}),(0,r.jsx)(t.p,{children:"But you're going to see more of this scorched.\r\nYeah. That's interesting.\r\nLook at these prints here. This is crazy, right?\r\nAnd as you go through here, they're deep, but look right here.\r\nAha!\r\nAh!\r\nSee?\r\nRight here.\r\nHe's going this way.\r\nWe think so.\r\nHe's going this way.\r\nWow. So you see what we're looking at here as far as like... We want you to kind of give us your perspective because we don't want to be making something out of nothing.\r\n(0:20:21)"}),(0,r.jsx)(t.p,{children:"Like you can see how these... Like this one to me looks like a hook almost.\r\nAlmost like a horse or something.\r\nAnd then there's the canine.\r\nAnd it's just... The canine one's over there and it keeps going.\r\nThe left side I think is different than the right.\r\nCan you show me what you're pointing at?\r\nSo it has this step and that step.\r\nAnd it's just stepping.\r\n(0:20:56)"}),(0,r.jsx)(t.p,{children:"But it's weird though how the almost humanoid prints disappeared though.\r\nYeah. They don't exist anymore in this range.\r\nAround that area.\r\nAs soon as it kind of gets into the clearing, you know?\r\nRight. As soon as it comes out of the brush.\r\nThen it gets into these.\r\nYeah. Like it's hidden where you can't see it even if you're over here or right there.\r\n(0:21:21)"}),(0,r.jsx)(t.p,{children:"But as soon as it comes out, you don't see a person walking.\r\nYou see whatever it is.\r\nSo... But... That though... I don't know.\r\nWhat are you... I mean... Like transfer this change that you were telling me.\r\nI knew exactly what you're talking about because we've seen things similar to that before.\r\nYeah. Like it stops there and then it gradually... As soon as it hits that point and then comes into these.\r\n(0:21:52)"}),(0,r.jsx)(t.p,{children:"Have you ever heard of... Have you ever heard of shapeshifters transforming into horses?\r\nLike tons of things.\r\nSo it's just pretty much anything.\r\nYeah. Any kind of animal would want to.\r\nNow, you said that shapeshifters can turn into horses.\r\nYeah. We've been finding what seems to be a lot of horse manure all over the place here.\r\n(0:22:23)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"And you hardly see horses around here.\r\nWe haven't seen one.\r\nExactly. And actually, there's a fresh pile next to the tree we just came in by.\r\nAnd I just don't know if it's horse manure or not.\r\nBut it looks... I'm not touching my hands.\r\nYeah. But it looks fresh and it wasn't there just the other day.\r\nGoing back to my history, my family history, my grandfather would transform into many different things.\r\n(0:22:49)"}),(0,r.jsx)(t.p,{children:"Whatever the circumstance that he needed.\r\nSometimes he would transform into a fox, coyote, a horse.\r\nSo as people who aren't from here and stuff, we're not making a stretch or a leap here just by seeing that.\r\nObviously, we're out here looking for a shapeshifter.\r\nBut to come across that, where did the human prints go?\r\nAnd where did this horse pop up out of nowhere?\r\n(0:23:15)"}),(0,r.jsx)(t.p,{children:"Yeah. Well, you look at it like this.\r\nWhy would these guys be out here doing this stuff, you know?\r\nIt's just like... That's what I see.\r\nThey transform.\r\nThat's what they do.\r\nThey come out to places like this.\r\nI mean... I don't like to talk about it too much because it sounds like it's really ridiculous.\r\nBut that's what they do.\r\nThey transform themselves into whatever entity, animal that they're trying to embody.\r\n(0:23:52)"}),(0,r.jsx)(t.p,{children:"And there's a lot of stories of Native Americans who used to transform into those things.\r\nWould become birds and fly over the forts and stuff.\r\nScout out viewpoints and reference points for their tribal usage so they could easily maneuver around those kind of areas.\r\nIt's not ridiculous because why are these transformation points out here?\r\nPeople run across them all the time. A lot of people don't know what they are.\r\n(0:24:23)"}),(0,r.jsx)(t.p,{children:"But that's what they're doing here.\r\nWe've had them right near our homes. Tribal members have seen these transformations.\r\nHave stumbled upon them out in the bush somewhere.\r\nSo we know these things take place.\r\nWe don't talk about them.\r\nAnd when we do, more times than not, people think we're crazy.\r\nCrazy Indians. But that's what occurs here is these things.\r\nAnd now you get to see some of the things.\r\n(0:24:50)"}),(0,r.jsx)(t.p,{children:"That would be one of the signs that you would look for is something transformational.\r\nFinding a trackway like this so early was really unexpected.\r\nBut having both Bo and Johnny sharing very similar perspectives really gave it a lot more credibility in our mind.\r\nEspecially given that a day prior, Christian and Joseph had interviewed a neighbor that actually reported watching an entity of some sort enter the property.\r\n(0:25:16)"}),(0,r.jsx)(t.p,{children:"Have you had any weird, seen weird things?\r\nI have. I never used to believe in what they call skinwalkers.\r\nAnd just right down the hill, I come in the other direction, you know, where it comes up to almost the top of the hill.\r\nThere'd come this big wolf, legs this long, and it was pure black.\r\nAnd its eyes, I can't describe as anything except for like light and a light bulb.\r\n(0:25:37)"}),(0,r.jsx)(t.p,{children:"But it was more like heat. It didn't have pupils or anything.\r\n(0:25:39)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"And it just wanted me to see it.\r\nAnd, you know, I mean, it was looking at me the whole time.\r\nAnd it wasn't even really touching the ground.\r\nYet it was walking. That's so hard to describe.\r\nAnd it gives me chills, too, just to talk about it.\r\nBut it wasn't a scary thing to me.\r\nAnd it did. It just wanted me to see it.\r\n(0:25:54)"}),(0,r.jsx)(t.p,{children:"It kept looking at me.\r\nAnd then it just disappeared across the whole mountain.\r\nI was like, wow. That is strange.\r\nAnd now I have a little bit more open mind for stuff like that.\r\nHave you seen... is that the only time you've ever seen a wolf out here?\r\nYeah. That's the only time I've ever seen anything like that.\r\nAnd I honestly didn't believe anybody.\r\n(0:26:09)"}),(0,r.jsx)(t.p,{children:"I would take a lie detector test about that because, I mean, I did see it.\r\nAnd I never believed stuff like that.\r\nHave you seen any wild animals out here or anything like that?\r\nNo. Just, uh... There's a lot of noise out here.\r\nI mean, all night long.\r\nThere was strange noises.\r\nNow, with the oil fields and everything else and the traffic now from the oil fields, I know pretty much what I'm hearing from around here.\r\n(0:26:36)"}),(0,r.jsx)(t.p,{children:"But inside of this house, just right here, you're always hearing somebody outside.\r\nI mean, if it's walking in the gravel or... Just, uh... Out in my yard.\r\nConstantly getting up and going and checking the door all the time.\r\nJust looking out and seeing if I see anybody out there.\r\nNever really is, but... Do you feel like there could be any connection between that and this property out here?\r\n(0:27:03)"}),(0,r.jsx)(t.p,{children:"And the walking around and... Yeah, there's something going on outside all the time.\r\nSeems like it's a paranormal dimension of some type or something to me.\r\nYou know, I mean... I don't understand a whole bunch about that kind of stuff.\r\nBut that's what I would take it as.\r\nI'm not an expert or anything, but I would take it definitely as something... that is... not necessarily of this world, but... Right. You know, it is.\r\n(0:27:31)"}),(0,r.jsx)(t.p,{children:"Because it's obviously here. I mean, that wolf thing was nothing but a shadow.\r\nBut it was in, you know, it was... I always lose the ability to talk about it because... it's so hard to describe or whatever.\r\nIt wasn't just like a shadow, but it wasn't a shadow.\r\nYou could see it clear as day.\r\nAnd as soon as, you know, I looked at it and my head followed across the street, I mean, it just disappeared. It was gone.\r\n(0:27:51)"}),(0,r.jsx)(t.p,{children:"As night fell, we had no idea what lay waiting for us outside the reach of the fire's light.\r\nUntil an accidental discovery confirmed we had somehow landed right at ground zero.\r\nWe might be in for a long night.\r\nWhy?\r\nWe might be in for a long couple of nights.\r\nWe went down that trail where we saw the prints.\r\n(0:28:16)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"And we went back further looking for a place to put the game trail cams.\r\nWe found a little bridge to go back across the creek.\r\nAnd so we went back across the creek and went pounding around because we saw a tree that... would be a good spot to look over the trail.\r\nYeah. I'm starting to hang it and Ward... He walks away and I turn around and look over.\r\n(0:28:40)"}),(0,r.jsx)(t.p,{children:"And I said to him, is that what I think it is?\r\nAnd he's like, yep.\r\nAnd he's standing there.\r\nAnd what I saw, I thought was a skull.\r\nLike antlers and stuff, you know?\r\nAnd so I was like, oh, you know.\r\nAnd I told him, I said, it's kind of getting a little eerie back here.\r\nAnd he's like, yep.\r\nAnd when I got done hanging the camera, he's now standing next to me.\r\n(0:29:07)"}),(0,r.jsx)(t.p,{children:"And we're getting ready to walk away.\r\nAnd I was like, let me go check this out real quick because I wanted to see it.\r\nWhat, when I walked up close to it, I didn't realize at the time was it was a ritual circle.\r\nAnd it had a couple of different skulls.\r\nIt had a bowl in the middle of it.\r\nAnd this is what it looked like.\r\n(0:29:26)"}),(0,r.jsx)(t.p,{children:"Just pass it around.\r\nThere's a couple of pictures you can swipe through.\r\nIt ties in with that last story I told you in the interview.\r\nWith the rituals that have been happening around here.\r\nIt was literally maybe like 30, 40 feet away from where we were walking around this afternoon.\r\nOn the other side of the creek.\r\nSo I wonder if that's connected to what we saw.\r\n(0:29:57)"}),(0,r.jsx)(t.p,{children:"That way or that way?\r\nThat way.\r\nThat way.\r\nSo I wonder if it's connected to what we saw at the footpath.\r\nMaybe. Be careful with that. Stay, stay, stay away.\r\nHow recent would you say that is?\r\nCould be an ongoing thing. It looks like it's been a while.\r\nSo it might be like this.\r\nMaybe Ryan interrupted one of their spots.\r\nThis was their spot before he moved in.\r\n(0:30:25)"}),(0,r.jsx)(t.p,{children:"So maybe in their mind he's intruding.\r\nThe people on this are intruding on their deal.\r\nIn their view.\r\nSo this might be just a statement of some sort.\r\nWe're here and we're going to stay here or something like that.\r\nIt's a warfare. It's a form of warfare.\r\nIf you really think about it, that's what it was utilized for.\r\nWhen you see those things, when our people see that, that's a sign of war against you.\r\n(0:30:56)"}),(0,r.jsx)(t.p,{children:"They've invaded you and they've done their thing on your land.\r\nThey've put their flag there, right?\r\nThat's what they've done.\r\nAnd you believe this connects with the possible... It does.\r\nIt does connect.\r\nIt does, yeah.\r\nYeah, you guys are in it now.\r\nYou know, it almost looks like the crown of thorns.\r\nWhoa!\r\nIt was a little too dark to see what was... That's unbelievable, man. Get that over here.\r\n(0:31:29)"}),(0,r.jsx)(t.p,{children:"I'm going to wash my hands.\r\n(0:31:31)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"Wow. Oh, yeah, yeah, yeah.\r\nWe've got a light.\r\nYou might need to get your A7. I'm not quite sensitive enough to pick it up, I don't think.\r\nIt's gone.\r\nOh, man.\r\nIt's gone.\r\nBig white.\r\nI got it on camera.\r\nYou got it?\r\nI got a picture of it.\r\nWhatever that was.\r\nWell, there's something still lit up there, though.\r\nThere's none of this last night.\r\n(0:32:09)"}),(0,r.jsx)(t.p,{children:"Oh!\r\nYou see it?\r\nOh, my God. There is something pulsating like crazy.\r\nOh, you're looking at over here.\r\nI'm seeing it.\r\nI'm seeing it.\r\nIt's over here, too, though.\r\nYes, it's going nuts this time.\r\nOh, man, they're both going nuts.\r\nAll right, so I was talking to you guys earlier about the ritual circle and how things started heating up here when we started talking to the group about it.\r\n(0:32:34)"}),(0,r.jsx)(t.p,{children:"Well, we started getting lights out here over the ridge, and they've been nonstop.\r\nJoel?\r\nOh, man, here they come again.\r\nHere they come again.\r\nOh, man, it's huge.\r\nLook at that.\r\nWow. What's this one here?\r\nStraight ahead?\r\nWhat are you seeing out here? Describe to them what's going on.\r\nSo there's these red and white lights, and they're pulsating in a nonrhythmic pattern.\r\nSo they're just moving in this one spot, but they're not showing up in the same place at all.\r\n(0:33:15)"}),(0,r.jsx)(t.p,{children:"And sometimes they're getting super bright, and then sometimes they're not as bright.\r\nBut they're not in the same spot, so you know it's not a stationary light that's out there for planes or anything like that.\r\nThis is completely different.\r\nWe've seen lights pulsating throughout the ridge, too.\r\nOn the ridge, yep.\r\nSo it's just popped up right around the time they found this ritual circle.\r\n(0:33:35)"}),(0,r.jsx)(t.p,{children:"And that's where it started. These lights on the ridge way over from where we're looking now was shining up into the sky.\r\nOh!\r\nWhoa!\r\nOh!\r\nWhoa, that just lit up.\r\nThere it is. That's it.\r\nThat just lit up.\r\nThat's what I'm saying.\r\nYep, and now it's gone, right?\r\nOh, here they come.\r\nYep, yep.\r\nAll right, let's not yell too loud because I don't want them hearing us over there.\r\n(0:33:55)"}),(0,r.jsx)(t.p,{children:"Oh, my God. And it's gone.\r\nBut there's two more over there on the right.\r\nAnd it's moving.\r\nYep, I see it now.\r\nI see it now.\r\nYep, I know exactly what you're talking about, bro.\r\nYeah, but there's a red one that jumps in with them.\r\nWell, I can't see color on this.\r\nYeah, this is crazy.\r\nBut both of those were white.\r\nBut you see those two still right there, right?\r\n(0:34:10)"}),(0,r.jsx)(t.p,{children:"You still see the two?\r\nUh-huh. Okay, so... Oh, and look like... That has nothing to do with that red one, bro.\r\nThat's blue.\r\nThat's blue.\r\nIt's gone.\r\nIt's gone.\r\nMan, this thing is bright.\r\nWhat are we looking at?\r\nWhat is that?\r\nI have no idea.\r\nHang on a sec.\r\nI gotta get this one that I can get on the camera.\r\nHere. No, it's everywhere.\r\n(0:34:31)"}),(0,r.jsx)(t.p,{children:"You're not going to have that many planes in the sky.\r\n(0:34:33)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"Yo, these are moving.\r\nWhat is that in the sky, guys?\r\nLook where the plane's at, but look at the other one right there by it.\r\nJoel, you gotta come here and look at my camera, bro.\r\nOh, shit.\r\nHave you seen this pattern?\r\nOh, oh, oh.\r\nWhere is it?\r\nAfter recording sightings in the sky, we could not explain.\r\nWe started to wonder if the stories of the activity in the area being intelligent were true.\r\n(0:34:58)"}),(0,r.jsx)(t.p,{children:"It really seemed to us, as we were there living it, that the discovery of this altar and our attention on it at the campfire might have kicked off all this phenomena in the sky.\r\nAlright, so me and the whole crew are going down to the ritual site right now.\r\nIt is nighttime, and we're going to go check it out and see what happens.\r\n(0:35:19)"}),(0,r.jsx)(t.p,{children:"Because our natural reaction is to kind of just stay next to the fire.\r\nI think that's human.\r\nAnd so we're going to go against our reactions and our inclinations and go check out this ritual circle at nighttime.\r\nOh, oh, oh, wow.\r\nYep. Crystals. Multiple skulls.\r\nSkull bone.\r\nWhat's this? There's some kind of seed.\r\nThat's another offering.\r\nDon't touch too much. Don't want anything to touch right now.\r\n(0:36:04)"}),(0,r.jsx)(t.p,{children:"Don't touch it.\r\nIt still has skin on the skull.\r\nYes. I know Bo would know more than I do, but these are probably an offering of the seeds on this side of it.\r\nThe orientation of it is important, so if we knew which way, north, west, south.\r\nSo this is probably north.\r\nKeep your ears open.\r\nThat's as much as you can do right now.\r\n(0:36:32)"}),(0,r.jsx)(t.p,{children:"Yeah, no, I heard movements too.\r\nYou heard movements?\r\nYeah, we heard cracking.\r\nYeah. That way.\r\nSlightly. Almost like a rat. We don't see anything.\r\nAfter a wild first night, we wanted to get Johnny's perspective on the area in general and what could lie behind the strange things that seemed to manifest there.\r\nIt's just always been an amazing place when it comes to those types of paranormal activities.\r\n(0:37:31)"}),(0,r.jsx)(t.p,{children:"But it's been ongoing since I was a kid.\r\nWe're told all these stories and warnings and all sorts of things, so we live by those things.\r\nThe outside is just kind of starting to figure it out and take notice of what we've been noticing probably for thousands of years.\r\nYesterday we were checking out what we were just, for us, calling a boneyard.\r\nAnd we were followed back to where we were staying by a guy that saw us there.\r\n(0:38:03)"}),(0,r.jsx)(t.p,{children:"And he even stopped at the end of the driveway that we turned into and just stared at my vehicle as I was pulling in.\r\nAnd I didn't know if it was something that people noticed if you're not from around here and they kind of just follow you to make sure you're not up to any problems.\r\nYeah, I'll tell you this.\r\nOkay, so you were in a boneyard. I don't know exactly what you've seen or where it was.\r\n(0:38:27)"}),(0,r.jsx)(t.p,{children:"But when we talk about one specific activity, it's the skinwalker.\r\n(0:38:36)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"I call it a cult, basically.\r\nIt's a bad, spiritual, bad, evil. Basically, that's what we consider it to be.\r\nIt's bad energy.\r\nThere's a lot of that activity that goes around.\r\nAnd those are actually physical humans who go through that process.\r\nIn essence, they're like werewolves.\r\nHowever they became, there's all sorts of different ways.\r\nAnd it's not specific to one tribe. It's all over.\r\n(0:39:09)"}),(0,r.jsx)(t.p,{children:"It's a shapeshifting, right?\r\nYeah. So they have specific, different, you know, shapeshifters follow different alters, different medicine.\r\nIt's dark medicine.\r\nBecause we have good medicine and there's bad medicine.\r\nStraight out.\r\nThere's a lot of that that goes on.\r\nNative country, a lot of the reservations you go to, you will hear about it.\r\nCurses, different things that people have learned how to utilize these entities and these forces that are out there.\r\n(0:39:51)"}),(0,r.jsx)(t.p,{children:"So that's basically what they've done.\r\nHundreds, maybe thousands of years ago, a group had discovered these entities and become subservient to those entities, I guess.\r\nThat's what you would say.\r\nSo it's a dark force.\r\nIt's a dark force.\r\nSo on that topic of the shapeshifting, go ahead.\r\nJust keep your eye out.\r\nOkay. With what you just said, how prevalent would you say shapeshifters are around here?\r\n(0:40:23)"}),(0,r.jsx)(t.p,{children:"Is this something that is a hit and miss every once in a while?\r\nThere could be somebody in your presence that is like that or is it something that a lot of people pursue?\r\nI don't know how to say it.\r\nIt's just there's a few.\r\nOkay. There's a few.\r\nWhat are we watching for out here?\r\nThat's so vast.\r\nI mean aside from the fact that it's gorgeous.\r\n(0:40:45)"}),(0,r.jsx)(t.p,{children:"That rock looks... That's old grandmother rock right there.\r\nWow. This is where a lot of the activity goes.\r\nIt's just one of our sacred spots.\r\nThis whole area is all sacred hills.\r\nReally?\r\nYou can walk over there if you want to.\r\nDo you want to walk over there?\r\nYeah. Just take a look at some of the... I've noticed this.\r\nAnd like I was telling you with this skinwalk or whatever you want to call it.\r\n(0:41:18)"}),(0,r.jsx)(t.p,{children:"Bad guys.\r\nThere is a human entity that's pushing it.\r\nRight?\r\nThere's a human.\r\nLike even one of us.\r\nJoin that.\r\nDo those bad things.\r\nSo they do have their people.\r\nTheir guards.\r\nAnd I've noticed that.\r\nIn fact a few months ago.\r\nYeah about a couple months ago.\r\nIt was back in April. I was helping a friend.\r\nShe was just north of me on White Rocks Road. And they had been seeing these creatures around here.\r\n(0:41:48)"}),(0,r.jsx)(t.p,{children:"And in the trees it was shouting at them.\r\nAnd they were just like, what the heck is this?\r\nAnd one night one of them came into the house.\r\nScared, scared, scared her daughter.\r\nSo they called me.\r\nAnd I said, well let's pray.\r\nSo we went and did our thing to protect her house, her family.\r\nAnd we made a burial around her little ranch there.\r\n(0:42:10)"}),(0,r.jsx)(t.p,{children:"And so we left.\r\n(0:42:13)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"In fact, it's funny we're talking about this.\r\nBecause we came here to pray to leave some tobacco here.\r\nBecause of power in this place.\r\nSo we said, well let's come down here and we'll leave some tobacco for the old lady.\r\nAnd then we'll go back.\r\nSo we brought the tobacco here, which is an offering to the creator.\r\nAnd we went back.\r\nAnd we're in two vehicles.\r\n(0:42:34)"}),(0,r.jsx)(t.p,{children:"They went up the road to her house.\r\nAnd I was about to turn off the highway to go up the road to her house.\r\nHer son was with me.\r\nAnd I looked at the road just a little ways down the road, like from here to my pickup.\r\nAnd I seen this guy in a hood.\r\nHood just walking, kind of his head down.\r\nAnd so I said, I asked him, who is that?\r\n(0:42:56)"}),(0,r.jsx)(t.p,{children:"He didn't say much.\r\nOh, it's just somebody walking.\r\nSo we went up.\r\nIt was quite a way, maybe a little further than that.\r\nAnd I just dropped him off, turned back around, came back down the hill.\r\nAnd he was a little closer.\r\nAnd just as he was getting to the boundary, like where we prayed.\r\nAnd we left our medicine there.\r\nHe just, like something pushed him back.\r\n(0:43:14)"}),(0,r.jsx)(t.p,{children:"Something pushed him back.\r\nMade him go.\r\nAnd the weird thing was, if maybe if it was, oh, I forgot, so I got turned around.\r\nWhy didn't he go back down the highway?\r\nHe pushed him back and he went down into the trees.\r\nWow. Yeah. So, but I told, and that's something I was told to be careful.\r\nI've always noticed those things and seen those things.\r\n(0:43:36)"}),(0,r.jsx)(t.p,{children:"And since then, a lady tourist, my friend, she's told me that they've seen it again.\r\nBut he won't come through.\r\nHe's trying to come through, but he can't come through.\r\nSo this is just in this area right here.\r\nThe way I figure it, because I tracked a different, just over time and over the years, I've heard different stories from different places.\r\nAnd it all seems to follow, it follows, actually it follows the rivers.\r\n(0:44:04)"}),(0,r.jsx)(t.p,{children:"It follows the rivers.\r\nYou'll see a lot of activity along this river, north and south.\r\nAnd then right in where Skinwalker Ranch happens to be where the two rivers connect.\r\nAnd then you also have a lot of activity that's coming down the Duchesne River, Strawberry and Duchesne River. And it seems to follow some sort of a track or, you know, some line of power.\r\n(0:44:28)"}),(0,r.jsx)(t.p,{children:"In March I was walking on that side.\r\nAnd did you see all these weird formations, little ridges in the air?\r\nYeah. I was just looking at them.\r\nAnd a lot of them are really weird because they're supposed to be natural formations, but they don't look like they were naturally placed.\r\nRight angles, different things like that, so whatever it may be.\r\nAll of our prophecies kind of more or less tell the same thing.\r\n(0:44:53)"}),(0,r.jsx)(t.p,{children:"There's a big change coming, you know, even coincides with a lot of Christian and a lot of those teachings as well.\r\n(0:45:01)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"But with most natives, we're there. We've already started. It's already going.\r\nYou've already been acknowledging it.\r\nYeah. For a long time. When I was a kid, you know, they talk about that.\r\nSo given what you were talking about before with the burial sites and not disturbing ground, we've heard a lot of people suggest that all these oil rigs are disturbing the ground.\r\nYes, yes they are.\r\n(0:45:33)"}),(0,r.jsx)(t.p,{children:"So it's it's fathomable that these oil rigs are really drumming up a lot of activity.\r\nThey are drumming up a lot of activity.\r\nAnd I used to think about this and I actually proposed this to the tribe.\r\nThis is years ago, 20 some years ago, when there wasn't a lot of activity.\r\nBecause being from North Dakota, being a Lakota, that's probably how we would attend to things.\r\n(0:45:57)"}),(0,r.jsx)(t.p,{children:"So I said, every time we drill a wall, we should go and pray for that wall.\r\nWe should offer it because we don't know what we're drilling into.\r\nWe don't know what we're releasing, you know.\r\nSo yeah, I 100% believe that.\r\nI believe it to be true as you feel it.\r\nAnd there's been more activity since a lot of this oil activity has come to the basin.\r\n(0:46:25)"}),(0,r.jsx)(t.p,{children:"There's been more unidentified paranormal activities going around.\r\nAnd I definitely think there is a connection. Absolutely. Could the mesa really contain ancient burial sites or the remnants of an even older civilization?\r\nCould the recent oil boom in some way be upsetting the area and causing strange activity?\r\nAccording to many locals, the answer is yes.\r\nThe wolf that you saw and the sounds that you hear before or after the drilling?\r\n(0:46:55)"}),(0,r.jsx)(t.p,{children:"After. Yeah, it was definitely after.\r\nNow, that's interesting, don't you think? Yeah, I do.\r\nNo, I think it is.\r\nWith every situation, there is a multitude of factors playing into what is happening.\r\nAnd I think that one of the things that is happening is that there's been a lot of radiation fallout that has swept over this valley from the testing sites in Nevada due to the air currents.\r\n(0:47:26)"}),(0,r.jsx)(t.p,{children:"So I think there's a lot of radioactive material in the soil that when you dig, you disrupt this radioactive material.\r\nAnd so I think that's a caution on that just for our current history.\r\nBut I think if we're going back to ancient history, it's a burial ground for the tribal people.\r\nThey understand that there's this energy highway and they want their ancestors to travel this highway back to source.\r\n(0:47:50)"}),(0,r.jsx)(t.p,{children:"So they, you know, there's a burial ground right next to the ranch.\r\nThe ranch is pretty much built, that whole ridge is a burial ground.\r\nSo, you know, disrupting that is just its own offense in and of itself, you know.\r\nYeah, there's some really strange things going on.\r\nThere's activity that is kind of like rebooted around 2016, right around when this oil rig went in, right around when new ownership purchased.\r\n(0:48:21)"}),(0,r.jsx)(t.p,{children:"And it's very interesting.\r\n(0:48:26)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"There's a lot of people that say that people used to bury their dead in certain places, you know, Indian burial grounds.\r\nAnd so they have tons of them in this whole basin, just everywhere, sprawled out in any direction you go, you always see one.\r\nAnd, you know, the more they do that, the spirits of the dead or whatever you want to call them, you know, it unleashes that into the world.\r\n(0:48:54)"}),(0,r.jsx)(t.p,{children:"They have nowhere to go.\r\nTheir bodies, Native Americans, as far as, you know, they believe is when you die, you have to have your body connected.\r\nOr you have to have your body to be connected to the spirit world or to the Native American heaven, the hunting grounds.\r\nYou have to have your body here.\r\nSo when a Native American cremates themselves, they have no body to be connected to that world.\r\n(0:49:24)"}),(0,r.jsx)(t.p,{children:"But a lot of people did bury their dead with all their bodies, everything, their belongings.\r\nBut when these things happen, and it disturbs that, their spirits are disconnected, from my understanding, from that bridge.\r\nYou know, because something keeps their body here and they're up there.\r\nAnd a lot of them have to come down and see what's happening.\r\nCould this place really be some kind of energy highway, a ley line or path that draws the activity along it?\r\n(0:50:02)"}),(0,r.jsx)(t.p,{children:"Could burial sites be what energizes the shapeshifter rituals and medicine?\r\nOr is it something darker?\r\nWhat's there to fear about a shapeshifter?\r\nHave they been known to hurt people?\r\nYes, yes.\r\nSo as I was talking earlier, down there, we're talking like this was a form of warfare, you know.\r\nSo that was the purpose of it.\r\nSo they do carry medicine from that realm.\r\n(0:50:30)"}),(0,r.jsx)(t.p,{children:"This is all energized, they're all sponsored from this dark realm, from a specific point.\r\nSo they do have the ability to hurt people, to kill people, to take things from people.\r\nIt's all about control. I don't know exactly, I try not to know, but you know, it's all around us.\r\nWe hear a lot of things.\r\nI don't know, you know, it's just a bad, dark place for bad, dark people, you know.\r\n(0:51:00)"}),(0,r.jsx)(t.p,{children:"You came here as a youth pastor.\r\nYeah. In doing that, you have a set of beliefs that were well-defined before this.\r\nHas that been changed, altered, strengthened in any way this week?\r\nWhen we talk about all of these things like the evil entities and the guarding of yourself from these, you know.\r\nThis is what Johnny's talking about, you know, especially with guarding yourself with what he does with sage and prayer and everything.\r\n(0:51:37)"}),(0,r.jsx)(t.p,{children:"I mean, the Bible talks about, you know, preparing yourself with the armor of Christ, you know.\r\nAnd that's, in my mind, that's the comparison I see.\r\nBe aware of what's going on underneath you, no matter where you are, you know.\r\nBecause there might be some energy, some power that's there from way back, you know.\r\n(0:52:01)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"Even our people don't know, because we're newcomers to this area.\r\nSo our elders would always tell us, don't dig, don't do this, don't disturb things from the old people.\r\nThere were people before us, so we didn't mess with that, you know.\r\nBut do be aware of what's underneath you, you know.\r\nI've lived in cities, in Phoenix, in Chicago, and people build.\r\nAnd especially in Phoenix, there's been, there's probably thousands of cases building right over the Hohokam, you know, ruins and different things.\r\n(0:52:30)"}),(0,r.jsx)(t.p,{children:"And you have a lot of poltergeist activity around that area.\r\nBut people don't know why, so I'll say.\r\nSo know what's underneath you, know what's there, listen, don't disregard those stories, you know.\r\nAnd I think that's what's important.\r\nAnd that'll just enhance things, you know.\r\nIt'll enhance you, because it gives you more history, more insight to what's going on.\r\nBecause it's not just the past ten years since YouTube's been invented.\r\n(0:53:00)"}),(0,r.jsx)(t.p,{children:"No, we've been seeing this for a long time.\r\nBut things are changing, I guess that's what I'll tell you.\r\nAll our people say that.\r\nJust be prepared, things will get weird, things will change.\r\nYou don't have to speak for the entire tribe, but would a weight be lifted in a lot of people if they could tell their side of the story?\r\nYes. That's exactly what we had hoped to do by coming here.\r\n(0:53:30)"}),(0,r.jsx)(t.p,{children:"We hoped we could give voice to the experiences of those that had lived here the longest.\r\nSometimes the campfire stories you hear end up being true.\r\nThe next morning, anthropologist James Keenan, who had spent six years following the magnetic field shifts beneath the Uinta Basin, arrived at Space Wolf to take EMF readings.\r\nJames' data and anthropological insight into an even older civilization added yet another layer of meaning onto the happenings we had experienced.\r\n(0:53:59)"}),(0,r.jsx)(t.p,{children:"In this area you have from a negative 14 microtesla all the way up to an 89 microtesla with the average for this area being a 46. I believe it was 46 for right here.\r\nSo that's just what the magnetic differences are for each location in the earth all the way down to its core.\r\nA negative would mean that there's some type of cavity or void underground.\r\n(0:54:29)"}),(0,r.jsx)(t.p,{children:"The higher means there's something highly magnetic.\r\nTo go up to an 89, you're talking about something like a large magnet.\r\nBut what's insane is it's transient. It's moved.\r\nYou can't have a negative 14 to an 89 in the same location, yet this is one of four spots that I've found and it's in a diagonal line.\r\nThey perfectly match up at 8.34 degrees.\r\nAnd what's kind of crazy is that 8.34 degree heading goes right up to Blind Frog Ranch too.\r\n(0:54:57)"}),(0,r.jsx)(t.p,{children:"And then there's this whole underground cavern system too that we've been under in certain parts with a lot of flowing water.\r\nSo we're wondering if maybe that's how, if it's highly saline, there's positive ions, high magnesium.\r\n(0:55:15)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"My whole hypothesis is that there's some type of magnetic energy underground that's feeding to a relay.\r\nSo you have point A underground, there's a point B, whatever that may be, and then it's transmitting out into space.\r\nAnd whatever it is, there's several Navajo symbols and there's actually a Navajo book that the front cover has the same type of theory.\r\nAnd it's all tied into the Yinaldluxi, which is a skinwalker. That's what the Din\xe9 call them.\r\n(0:55:49)"}),(0,r.jsx)(t.p,{children:"And also with the symbols of the petroglyphs and the pictographs, and then also obviously UFO. Yeah, the giants is a whole other topic, but you'll see that in the petroglyphs at Dry Fork Canyon. I mean, seven feet plus in height, six digits on the fingers, massively large feet.\r\nSo they say the Citeka were the red-headed cannibal giants for this area.\r\nI don't believe they were cannibal, but they were headhunters.\r\n(0:56:20)"}),(0,r.jsx)(t.p,{children:"And you can see that in the anthropomorphic figures, or actually have taken heads, trophy heads.\r\nSo that may be where that came from.\r\nOkay, that's interesting. I've heard of the red-headed giants before.\r\nAnd so now that we know we can visit somewhere where they were depicted, I think it would be worth our time before we head back home.\r\nOh, absolutely. Even the three kings up at the top, you won't be able to get close, but with the camera you'll be able to zoom in.\r\n(0:56:46)"}),(0,r.jsx)(t.p,{children:"Consider the height factor of what you're looking at compared to what's around it.\r\nAnd there's one anthropomorphic figure over to the right.\r\nYou'll see the patina is a lot older than the rest of it.\r\nIt's truly an interesting rock art piece to look at, because that's just telling us that there was something about that site that was so important that it continued to be worked over and added to.\r\n(0:57:10)"}),(0,r.jsx)(t.p,{children:"And periods after.\r\nHad there really been giants here? How long has this high strangeness been going on?\r\nWe did in fact find a number of petroglyphs left by ancient and little understood Fremont cliff dwellers near the basin.\r\nAncient depictions of giants, shapeshifters, and even what some would call portals.\r\nWith new layers of context on the basin, we gathered around coffee to prepare for our last night on the property.\r\n(0:57:39)"}),(0,r.jsx)(t.p,{children:"Going into tonight, I feel like my headspace is just more understanding compared to what it has been the past couple of days.\r\nSpending time with Johnny and Bo and understanding their culture, I understand a little bit more as to what kind of makes up this area and the essence of what's been going on.\r\nAnd we'll see what happens tonight with that.\r\nBut I definitely feel like I'm coming from a more educated understanding.\r\n(0:58:08)"}),(0,r.jsx)(t.p,{children:"And as a result of that, I might go through an experience tonight that I might view differently than I would have two days ago.\r\nYeah, I think I kind of have a patient mindset tonight.\r\nWe came in kind of like guns ablaze and we were excited to get going.\r\n(0:58:25)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"And now that we've had that experience with talking with both Bo and Johnny and others around the area, it kind of helps to settle that excitement down.\r\nBut also knowing that we're in the presence of a lot of other things going on.\r\nSo I'm pretty patient.\r\nYeah, so for me, it's two things.\r\nOne was last night around the fireplace when Johnny sat there and told us that he felt like that we've come in with reverence and respect.\r\n(0:58:54)"}),(0,r.jsx)(t.p,{children:"And he feels like the people that do that tend to see what they have come to see.\r\nAlso, I think just from a perspective of who we are as a team, I think that's what we bring to the table.\r\nWe don't come in here just trying to stir things up just for the sake of it.\r\nI think we want to go about it the right way.\r\n(0:59:10)"}),(0,r.jsx)(t.p,{children:"We want to do it in a respectful way and also a safe way.\r\nBut I feel real good about tonight.\r\nI've been getting that feeling since I woke up this morning.\r\nAnd I know that place is just a hotbed ready to explode.\r\nHearing the experiences of the people that lived here and having our own strange encounters earlier in the week, we were all excited for what our final night at Space Wolf would hold.\r\n(0:59:32)"}),(0,r.jsx)(t.p,{children:"Unfortunately, the night took a turn none of us expected.\r\nSo back there when Jack was saying he saw that blue light blinking, which is obviously some sort of tower or something like that.\r\nAs we were pulling past, I noticed there was a dirt road next to us and headlights lit up.\r\nAnd I said, well, that's kind of odd. They're on a dirt road. There's nothing back that way.\r\n(0:59:55)"}),(0,r.jsx)(t.p,{children:"And I started turning around and watching.\r\nAnd they slowly pulled out. They waited though for us to get way down.\r\nAnd they pulled out and they essentially followed us.\r\nAnd that's why I asked Tony to stop because it just seemed odd.\r\nI wanted to see what they did.\r\n(1:00:19)"}),(0,r.jsx)(t.p,{children:"Well, they did come by there, but they did slow up by the entrance to Space Wolf. But they kept going obviously because they saw us stopped. We didn't go all the way back to the campsite.\r\nSo currently we are trying to follow them.\r\nJoseph just called me. So one of you guys could maybe call him.\r\nYeah, somebody called Joseph. A truck hidden in the high desert had evidently been waiting for us to pass.\r\n(1:00:39)"}),(0,r.jsx)(t.p,{children:"When we pulled into the driveway at Space Wolf, the following car slowed to a stop at the gate.\r\nWhen they saw Joel get out of the vehicle and acknowledge them, they sped off.\r\nIn the heat of the moment, we decided to follow.\r\nIt looked like they sped up. I'm telling you, man, it's weird.\r\nThere's no... It was like that classic... They were in the dark the whole time until we came driving by and then the lights lit up.\r\n(1:01:05)"}),(0,r.jsx)(t.p,{children:"Yeah. Well, that's odd how far out there he got.\r\n(1:01:12)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"I know, he sped up big time.\r\nI have a feeling this guy is going to disengage on us.\r\nKeep an eye out left and right too. He pulled off.\r\nYeah, look left, look left, look left.\r\nThere are protectors.\r\nThat's some good stuff.\r\nI mean, he's trying to tell me to turn, but... Careening down back roads at speeds of 90 or more, the car that had been following got away from us.\r\n(1:01:49)"}),(0,r.jsx)(t.p,{children:"During this chase, however, we got a call from Joseph back at our base camp.\r\nHe had stayed behind that evening and so had seen that after we pulled out to chase the follow car, yet another vehicle had pulled into Space Wolf driveway and presumably would have continued all the way down to our campsite if Joseph hadn't flashed a strobing tactical flashlight at them.\r\n(1:02:10)"}),(0,r.jsx)(t.p,{children:"Get ready to text him that we're at the gate.\r\nYou got it, Christian?\r\nYeah. I've never seen a vehicle go around corners that fast though.\r\nThat was that, like it's a pickup truck.\r\nYeah, he was pushing it.\r\nHe made distance on us.\r\nIt's kind of hard to do that with as much stuff as what we have.\r\nYeah, he got more weight.\r\nYeah. We'll find out how far this car came down. Did it just come in here?\r\n(1:02:42)"}),(0,r.jsx)(t.p,{children:"Look at that though, you can still see the dust in the air.\r\nYeah. I mean, that's what I thought when I saw that car pull up. The lights went off, all you saw was lights.\r\nWhen did you turn the lights on? Like right before you turned it in?\r\nSo as it turned in, they went off before it completed its turn, rolled in, and I thought it was Chester's, a friend of Chester's or something.\r\n(1:03:05)"}),(0,r.jsx)(t.p,{children:"You know? And then he just kept coming, coming, coming, and I was like, oh no, no, no, no.\r\nDid it stop before you did that or after?\r\nNo, it stopped when I did this.\r\nSo like that stopped it?\r\nAnd then it backed up.\r\nDid it back up in a hurry when you did that?\r\nNo. No, because I think it figured out how far I was away, but I'm thinking, what if those guys, whoever that was, a decoy, to pull you guys away and then somebody comes in here.\r\n(1:03:36)"}),(0,r.jsx)(t.p,{children:"Well, this car was like, I mean, I would just call it a Camry, that kind of car.\r\nYeah, like a four-door. Could you tell Colin to turn it on?\r\nNo, I couldn't, it was too dark.\r\nSee that light? That's a motion sensor.\r\nThat's the light that first alerted me to it, just as it like... So it's probably at 20, 30, or 60 seconds.\r\n(1:03:59)"}),(0,r.jsx)(t.p,{children:"There you go.\r\nThere it goes.\r\n30 seconds.\r\nWhich means it kicked on.\r\nBeing in a threatening situation put a massive damper on the final night.\r\nWe became less worried about the unexplainable and more about our own physical security.\r\nObviously, someone had wanted into our camp.\r\n(1:04:29)"}),(0,r.jsx)(t.hr,{}),(0,r.jsx)(t.p,{children:"But for what purpose, we don't know.\r\nCould there have been something we weren't supposed to know?\r\nWas it intimidation?\r\nOr just letting us know we were being watched?\r\nWe did not bring the K2. Just saw it now.\r\nDo you think that there's ancient curses on this land, these lands and stuff, that might attract the activity that has been happening here?\r\nI mean, we're talking about upright walking dogs, giant wolves.\r\n(1:05:15)"}),(0,r.jsx)(t.p,{children:"We're talking about UFOs, abductions, rake-looking type creatures.\r\nThere's so much going on here in this area.\r\nDo you think that there could have been an ancient curse put on this land that has been almost like a magnet for all this stuff?\r\nI didn't really know. I thought up until the point he was actually... I don't know if it was a he or a she.\r\n(1:05:38)"}),(0,r.jsx)(t.p,{children:"We were in the vehicle, and I don't even know exactly what it was, because I never got a full look at it.\r\nBut it seemed like an interesting, possibly interdimensional type, now that I look back.\r\nBut it was a very just... For all intents and purposes, what I saw was an older Native American in the middle of nowhere.\r\nNatives were very resistant to telling anything, because we didn't want to be diagnosed as crazy.\r\n(1:06:11)"}),(0,r.jsx)(t.p,{children:"That's true. So we kind of kept quiet and just kept it among ourselves.\r\nWe didn't really talk until recently.\r\nBut then at the same time, no one really asked us either.\r\nCould you define for the audience what a skinwalker is?\r\nI mean, there's a lot of people that define it differently, I've heard at least.\r\nBut what would you say a skinwalker is?\r\nIt is a mixture of things, and it really depends on what culture is defining it.\r\n(1:06:44)"}),(0,r.jsx)(t.p,{children:"Whether that be the Native Americans defining it as a skinwalker, or a dark arts practicing witchery way of following dark shaman, appears to be something they are not. Magic, perfectly explained, really.\r\nIn the paranormal community, few places elicit as strong an association with the truly unexplained as this cut of high desert.\r\nCould it be that this place is set apart in some way sacred or desecrated?\r\n(1:07:20)"}),(0,r.jsx)(t.p,{children:"Why are experiences here so common, so vivid?\r\nOut at the margins of reality, questions abound while answers are rare.\r\nIt's poetry, not a technical manual.\r\nWhat I do know, is that if you listen to the sounds that have hung over this place the longest, the voices of those with the longest memories, you can start to catch the rhythm.\r\n(1:07:43)"})]}),"\n",(0,r.jsx)(t.p,{children:"(2024-12-04)"})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>i,x:()=>h});var o=n(296540);const r={},a=o.createContext(r);function i(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),o.createElement(a.Provider,{value:t},e.children)}},901158:e=>{e.exports=JSON.parse('{"permalink":"/ds/blog/2024/12/04/burn_tree_foot_trace","source":"@site/blog/2024-12-04-burn_tree_foot_trace.md","title":"\u52d5\u753b\uff1aSkinwalker ranch \u306b\u96a3\u63a5\u3057\u305f\u6240\u6709\u5730\u3067\u8d77\u304d\u308b\u602a\u73fe\u8c61\uff1a\u6587\u5b57\u8d77\u3053\u3057","description":"\u524d\u7f6e\u304d","date":"2024-12-04T00:00:00.000Z","tags":[{"inline":false,"label":"occult","permalink":"/ds/blog/tags/occult","description":"occult"},{"inline":false,"label":"2024-12","permalink":"/ds/blog/tags/2024-12","description":"2024-12"}],"readingTime":52.74,"hasTruncateMarker":true,"authors":[],"frontMatter":{"tags":["occult","2024-12"]},"unlisted":false,"prevItem":{"title":"\u300c\u9014\u4e2d\u3067\u9014\u5207\u308c\u305f Bigfoot \u306e\u8db3\u8de1\u300d\u306e\u8b0e\u3092\u89e3\u304f \uff08\u9014\u4e2d1\uff09","permalink":"/ds/blog/2024/12/04/banished_footprints"},"nextItem":{"title":"\\"MUFO man\\" \u306e Youtube \u52d5\u753b\u306e\u30ec\u30d9\u30eb","permalink":"/ds/blog/2024/12/04/drone"}}')}}]);